<template><section class="page-content pos-page"><div class="page-heading"><div><p class="eyebrow">TRANSAKSI PENJUALAN</p><h1>{{ editing ? 'Edit Transaksi' : 'Transaksi Baru' }}</h1><p class="page-description">Lengkapi detail pelanggan, barang, dan pembayaran.</p></div><button class="button button-secondary" type="button" @click="router.push('/pos')">Kembali</button></div><form class="panel purchase-page-form" @submit.prevent="save()"><div class="purchase-form-body"><div class="form-section"><h3>Informasi Transaksi</h3><div class="form-grid"><label class="field"><span>Tanggal Transaksi</span><input v-model="form.tanggal" type="date" required /></label><label class="field"><span>Nama Pelanggan <small>(optional)</small></span><input v-model="form.pelangganNama" list="customer-options" placeholder="Umum atau pilih pelanggan" @change="selectCustomer" /><datalist id="customer-options"><option v-for="customer in customers" :key="customer.id" :value="customer.nama" /></datalist></label><label class="field"><span>Metode Pembayaran</span><select v-model="form.metodePembayaran"><option value="cash">Cash</option><option value="qris">QRIS</option><option value="utang">Utang</option></select></label><label class="field field-wide"><span>Catatan / Keterangan</span><textarea v-model="form.catatan" rows="2" placeholder="Catatan transaksi" /></label></div></div><div class="purchase-items-heading"><div><h3>Daftar Produk</h3><p>Pilih produk manual atau masukkan barcode untuk mencari.</p></div><button class="button button-secondary" type="button" @click="addItem">+ Tambah Produk</button></div><div class="pos-scan-row"><div class="barcode-input-wrap"><input v-model="barcode" placeholder="Scan / masukkan barcode produk" @keyup.enter="scanProduct" /><button class="barcode-scan-button" type="button" aria-label="Buka kamera scanner" @click="startScanner">⌁</button></div><button class="button button-secondary" type="button" @click="scanProduct">Cari</button></div><div class="purchase-items"><div v-for="(item, index) in form.items" :key="item.key" class="purchase-item"><span class="item-number">{{ index + 1 }}</span><label class="field item-product"><span>Produk</span><select v-model="item.produkId" @change="syncProduct(item)"><option value="">Pilih produk</option><option v-for="product in products" :key="product.id" :value="product.id">{{ product.nama }}</option></select></label><label class="field item-quantity"><span>Jumlah</span><input v-model.number="item.jumlah" min="1" type="number" /></label><div class="item-total">{{ formatRupiah(item.jumlah * item.hargaJualUnit) }}</div><button class="remove-item" type="button" @click="removeItem(index)">×</button></div></div><div class="purchase-total"><span>Total Penjualan</span><strong>{{ formatRupiah(total) }}</strong></div><p v-if="errorMessage" class="profile-message error">{{ errorMessage }}</p><div class="form-actions"><button class="button button-secondary" type="button" @click="router.push('/pos')">Batal</button><button class="button button-primary" type="submit" :disabled="saving">{{ saving ? 'Menyimpan...' : 'Simpan sebagai Draft' }}</button></div></div><div v-if="showScanner" class="scanner-overlay" @click.self="stopScanner"><div class="scanner-card"><div class="scanner-card-heading"><div><p class="eyebrow">SCAN BARCODE</p><h3>Pindai Produk</h3></div><button class="modal-close" type="button" @click="stopScanner">×</button></div><p>Arahkan kamera ke barcode produk. Produk akan ditambahkan otomatis.</p><video ref="videoRef" class="scanner-video"></video><button class="button button-secondary scanner-close-button" type="button" @click="stopScanner">Tutup Kamera</button></div></div><div class="form-actions"><button class="button button-secondary" type="submit" :disabled="saving">{{ saving ? 'Menyimpan...' : 'Simpan Draft' }}</button><button class="button button-primary" type="button" :disabled="saving" @click="save(true)">{{ saving ? 'Memproses...' : 'Simpan & Kunci Transaksi' }}</button></div></form></section></template>
<script setup lang="ts">import { computed, onMounted, ref } from 'vue'; import { BrowserMultiFormatReader } from '@zxing/browser'; import { addDoc, collection, doc, getDocs, getDoc, updateDoc } from 'firebase/firestore'; import { useRoute, useRouter } from 'vue-router'; import { db } from '@/firebase'; import { authState } from '@/auth'; const router=useRouter(); const route=useRoute(); const products=ref<any[]>([]); const customers=ref<any[]>([]); const saving=ref(false); const errorMessage=ref(''); const barcode=ref(''); const showScanner=ref(false); const videoRef=ref<HTMLVideoElement|null>(null); let codeReader:BrowserMultiFormatReader|null=null; const editing= computed(()=>Boolean(route.params.id)); const form=ref<any>({ tanggal:new Date().toISOString().slice(0,10), pelangganId:'', pelangganNama:'', metodePembayaran:'cash', catatan:'', items:[] }); const base=()=>`warungs/${authState.warungId}`; const formatRupiah=(value:number)=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value||0); const total=computed(()=>form.value.items.reduce((sum:any,item:any)=>sum+Number(item.jumlah||0)*Number(item.hargaJualUnit||0),0)); const addItem=()=>form.value.items.push({key:`${Date.now()}-${Math.random()}`,produkId:'',nama:'',jumlah:1,hargaJualUnit:0}); const removeItem=(index:number)=>form.value.items.splice(index,1); const syncProduct=(item:any)=>{const product=products.value.find((value)=>value.id===item.produkId); if(product){item.nama=product.nama; item.hargaJualUnit=Number(product.hargaJualReal||product.hargaJualPerUnit||0)}}; const selectCustomer=()=>{const customer=customers.value.find((value)=>value.nama===form.value.pelangganNama); form.value.pelangganId=customer?.id||''}; const startScanner=async()=>{showScanner.value=true; codeReader=new BrowserMultiFormatReader(); try{const devices=await BrowserMultiFormatReader.listVideoInputDevices(); if(devices[0]&&videoRef.value) codeReader.decodeFromVideoDevice(devices[0].deviceId,videoRef.value,(result)=>{if(result){barcode.value=result.getText(); stopScanner(); scanProduct()}})}catch{showScanner.value=false; errorMessage.value='Kamera tidak dapat diakses. Pastikan izin kamera diberikan.'}}; const stopScanner=()=>{const stream=videoRef.value?.srcObject as MediaStream|null; stream?.getTracks().forEach((track)=>track.stop()); if(videoRef.value) videoRef.value.srcObject=null; showScanner.value=false}; const scanProduct=()=>{const product=products.value.find((value)=>value.barcode===barcode.value); if(product){const existing=form.value.items.find((item:any)=>item.produkId===product.id); if(existing) existing.jumlah+=1; else {addItem(); const item=form.value.items.at(-1); item.produkId=product.id; syncProduct(item)} barcode.value=''}}; const save=async(lock=false)=>{if(!form.value.items.length||form.value.items.some((item:any)=>!item.produkId)){errorMessage.value='Tambahkan minimal satu produk.';return} saving.value=true; try {let customerId=form.value.pelangganId; if(form.value.pelangganNama&&!customerId){const customer=await addDoc(collection(db,base(),'customers'),{nama:form.value.pelangganNama.trim(),createdAt:new Date().toISOString()});customerId=customer.id} const payload={...form.value, pelangganId:customerId,total:total.value,status:lock?'locked':'draft',createdAt:new Date().toISOString()}; if(editing.value) await updateDoc(doc(db,base(),'sales',route.params.id as string),payload); else await addDoc(collection(db,base(),'sales'),payload); await router.push('/pos')} catch(error:any){errorMessage.value=error?.message||'Gagal menyimpan transaksi.'} finally{saving.value=false}}; onMounted(async()=>{if(!authState.warungId)return; const [productsSnapshot,customersSnapshot]=await Promise.all([getDocs(collection(db,base(),'produk')),getDocs(collection(db,base(),'customers'))]); products.value=productsSnapshot.docs.map((item)=>({id:item.id,...item.data()})); customers.value=customersSnapshot.docs.map((item)=>({id:item.id,...item.data()})); if(editing.value){const snapshot=await getDoc(doc(db,base(),'sales',route.params.id as string)); if(snapshot.exists()) form.value={...snapshot.data(),items:(snapshot.data().items||[]).map((item:any)=>({...item,key:`${Date.now()}-${Math.random()}`}))}} else addItem()})
</script>
